mapper.select:
select id, name, path, title, note, icon, component, redirect, affix, hidden, parent_id, `order`, deleted, create_time, create_user, update_time, update_user from permission
name like concat('%',#{permission.name},'%')
and path =#{permission.path}
and entity =#{permission.note}
and deleted=0 order by `order`,create_time desc,update_time desc

select count(1)
from permission


        and path =#{per.path}


        and component =#{per.component}
